function validate([source, target, original, changed, cost]) {
  const lower = /^[a-z]+$/;
  if (typeof source !== 'string' || typeof target !== 'string' || !lower.test(source) || !lower.test(target)) return 'source and target must be non-empty strings of lowercase letters.';
  if (source.length !== target.length) return 'source and target must have the same length.';
  if (source.length > 100000) return 'source has at most 10^5 letters.';
  if (!Array.isArray(original) || !Array.isArray(changed) || !Array.isArray(cost)) return 'original, changed and cost must be arrays.';
  if (original.length < 1 || original.length > 2000) return 'original needs 1 to 2000 entries.';
  if (changed.length !== original.length || cost.length !== original.length) return 'original, changed and cost must have the same length.';
  for (let j = 0; j < original.length; j++) {
    if (typeof original[j] !== 'string' || typeof changed[j] !== 'string' || !/^[a-z]$/.test(original[j]) || !/^[a-z]$/.test(changed[j])) return 'original and changed hold single lowercase letters.';
    if (original[j] === changed[j]) return 'original[i] and changed[i] must differ.';
    if (!Number.isInteger(cost[j]) || cost[j] < 1 || cost[j] > 1000000) return 'Each cost is a whole number from 1 to 10^6.';
  }
  return null;
}

