function minimumCost(source, target, original, changed, cost) {
  const dist = Array.from({ length: 26 }, () => new Array(26).fill(Infinity));
  for (let letter = 0; letter < 26; letter++) {
    dist[letter][letter] = 0;
  }
  for (let i = 0; i < original.length; i++) {
    const from = original[i].charCodeAt(0) - 97;
    const to = changed[i].charCodeAt(0) - 97;
    dist[from][to] = Math.min(dist[from][to], cost[i]);
  }

  for (let mid = 0; mid < 26; mid++) {
    for (let from = 0; from < 26; from++) {
      for (let to = 0; to < 26; to++) {
        if (dist[from][mid] + dist[mid][to] < dist[from][to]) {
          dist[from][to] = dist[from][mid] + dist[mid][to];
        }
      }
    }
  }

  let total = 0;
  for (let i = 0; i < source.length; i++) {
    const step = dist[source.charCodeAt(i) - 97][target.charCodeAt(i) - 97];
    if (step === Infinity) {
      return -1;
    }
    total += step;
  }
  return total;
}

