function minimumCost(source, target, original, changed, cost) {
  // For each position, relax every rule until nothing improves (Bellman-Ford from the source letter).
  let sum = 0;
  for (let p = 0; p < source.length; p++) {
    const best = new Map();
    best.set(source[p], 0);
    let changedAny = true;
    while (changedAny) {
      changedAny = false;
      for (let j = 0; j < original.length; j++) {
        if (!best.has(original[j])) continue;
        const price = best.get(original[j]) + cost[j];
        if (!best.has(changed[j]) || price < best.get(changed[j])) { best.set(changed[j], price); changedAny = true; }
      }
    }
    if (!best.has(target[p])) return -1;
    sum += best.get(target[p]);
  }
  return sum;
}

