function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 26 : 2 + Math.floor(rand() * 4);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * letters));
  const n = large ? 10000 : 1 + Math.floor(rand() * 8);
  const m = large ? 500 + Math.floor(rand() * 1501) : 1 + Math.floor(rand() * 8);
  const keep = rand() * 0.6;
  let source = '', target = '';
  for (let i = 0; i < n; i++) {
    const s = letter();
    source += s;
    target += rand() < keep ? s : letter();
  }
  const original = [], changed = [], cost = [];
  const top = large ? 1000000 : 1 + Math.floor(rand() * 20);
  for (let j = 0; j < m; j++) {
    const from = letter();
    let to = letter();
    while (to === from) to = letter();
    original.push(from);
    changed.push(to);
    cost.push(1 + Math.floor(rand() * top));
  }
  return [source, target, original, changed, cost];
}
